import java.util.*;

class Solution {
    public int maxTreasure(int[][] grid) {
        int best = 0;
        for (int i = 0; i < grid.length; i++)
            for (int j = 0; j < grid[0].length; j++)
                if (grid[i][j] > 0) best = Math.max(best, dfs(grid, i, j));
        return best;
    }

    private int dfs(int[][] g, int i, int j) {
        if (i < 0 || j < 0 || i >= g.length || j >= g[0].length || g[i][j] == 0) return 0;
        int v = g[i][j];
        g[i][j] = 0;                       // mark visited
        int best = Math.max(Math.max(dfs(g, i + 1, j), dfs(g, i - 1, j)),
                            Math.max(dfs(g, i, j + 1), dfs(g, i, j - 1)));
        g[i][j] = v;                       // undo (backtrack)
        return v + best;
    }
}

