class Solution:
    def maxTreasure(self, grid: List[List[int]]) -> int:
        R, C = len(grid), len(grid[0])
        def dfs(i, j):
            if not (0 <= i < R and 0 <= j < C) or grid[i][j] == 0: return 0
            v = grid[i][j]; grid[i][j] = 0
            best = max(dfs(i + 1, j), dfs(i - 1, j), dfs(i, j + 1), dfs(i, j - 1))
            grid[i][j] = v
            return v + best
        return max(dfs(i, j) for i in range(R) for j in range(C))

