function maxTreasure(grid) {
  const R = grid.length, C = grid[0].length, vis = grid.map(r => r.map(() => false)); let best = 0;
  function go(i, j, acc) {
    acc += grid[i][j]; if (acc > best) best = acc; vis[i][j] = true;
    for (const [a, b] of [[i + 1, j], [i - 1, j], [i, j + 1], [i, j - 1]])
      if (a >= 0 && a < R && b >= 0 && b < C && grid[a][b] > 0 && !vis[a][b]) go(a, b, acc);
    vis[i][j] = false;
  }
  for (let i = 0; i < R; i++) for (let j = 0; j < C; j++) if (grid[i][j] > 0) go(i, j, 0);
  return best;
}
